const BOAT_RUNS=[600,720,840]; // corse della barca a motore: 10, 12, 14
function nextRun(){return BOAT_RUNS.find(t=>t>=S.clock)}
function boatPrice(){return Math.round(30*MESI[S.mese].prezzi)}
function lakeFlood(){if(S.lakeFlood===undefined){const h=S.wxHist||[],y=h[h.length-1],y2=h[h.length-2];S.lakeFlood=(y==='pioggia'&&y2==='pioggia')||(y==='pioggia'&&chance(0.7))}return S.lakeFlood}
function lakeBoats(){if(S.lakeBoats===undefined){S.lakeBoats=lakeFlood()?0:(chance(0.5)?1:2);S.lakeMate=chance(0.25)}return S.lakeBoats}
function rowCost(){const wind=S.wx==='vento'?1.5:1,one=lakeBoats()===1;return{min:Math.round(30*(one?3:1)*wind),e:Math.round((one?22:8)*wind*(S.lakeMate?0.5:1))}}
function rowOut(){const one=lakeBoats()===1,mate=S.lakeMate,c=rowCost(),wind=S.wx==='vento';
 const txt=(one?`Remi fino all'altra sponda, leghi la seconda barca alla tua, la riporti indietro e riattraversi.`:`Prendi una delle due barche e attraversi. L'altra resta per chi viene dopo.`)+(mate?` Remate in due: la fatica si dimezza.`:'')+(wind?' Il vento alza le onde, ogni colpo di remo vale la metà.':'');
 const f=Object.assign({min:c.min,e:-c.e,m:mate?4:one?-4:2},mate?{mem:'rematore'}:{});
 return [O(4,one&&!mate?'m':'g',txt,f),O(1,'m',txt+' A metà lago un remo scivola fuori dallo scalmo: lo recuperi, ma perdi tempo.',Object.assign({},f,{min:c.min+10,e:-c.e-3}))]}
